// Package cli: config=2, network=3, cluster=4, auth=5,
//              unknown-flag=64 (EX_USAGE), other=1,
//              SIGINT=130, SIGTERM=143, success=0.
func exitCodeFor(err error) int {
    var cfgErr *errtypes.ConfigError; if errors.As(err, &cfgErr) { return 2 }
    var netErr *errtypes.NetworkError; if errors.As(err, &netErr) { return 3 }
    var clusterErr *errtypes.ClusterError; if errors.As(err, &clusterErr) { return 4 }
    var authErr *errtypes.AuthError; if errors.As(err, &authErr) { return 5 }
    return 1
}

